import{_ as e,o as l,c as o,a2 as t}from"./chunks/framework.z3u3TMv0.js";const P=JSON.parse('{"title":"安裝 KoboldCPP","description":"安裝 KoboldCPP，加載 GGUF，為 MiniTavern 提供 OpenAI 兼容 API（角色扮演常用）。","frontmatter":{"title":"安裝 KoboldCPP","description":"安裝 KoboldCPP，加載 GGUF，為 MiniTavern 提供 OpenAI 兼容 API（角色扮演常用）。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"安裝 KoboldCPP · MiniTavern Docs"}],["meta",{"property":"og:description","content":"安裝 KoboldCPP，加載 GGUF，為 MiniTavern 提供 OpenAI 兼容 API（角色扮演常用）。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/koboldcpp/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/koboldcpp/install"}]]},"headers":[],"relativePath":"zh-TW/koboldcpp/install.md","filePath":"zh-TW/koboldcpp/install.md","lastUpdated":1787224147000}'),i={name:"zh-TW/koboldcpp/install.md"};function n(r,a,d,s,p,c){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="安裝與上手-koboldcpp" tabindex="-1">安裝與上手（KoboldCPP） <a class="header-anchor" href="#安裝與上手-koboldcpp" aria-label="Permalink to &quot;安裝與上手（KoboldCPP）&quot;">​</a></h1><p><a href="https://github.com/LostRuins/koboldcpp" target="_blank" rel="noreferrer">KoboldCPP</a> 基於 llama.cpp，帶輕量界面，在角色扮演社區很常見，可開啟 <strong>OpenAI 兼容</strong> HTTP API，供 MiniTavern 連接。</p><h2 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to &quot;安裝&quot;">​</a></h2><ol><li>打開 GitHub Releases，按系統下載對應構建（Windows 常有獨立 <code>.exe</code>；其它系統按說明編譯或使用發佈包）。</li><li>首次運行按提示選擇後端（CUDA / Metal / Vulkan / CPU 等），以你硬件為準。</li><li>準備一個 <strong>GGUF</strong> 模型文件（見 <a href="/ultra_guides/zh-TW/local/models">推薦模型</a>）。</li></ol><h2 id="加載模型" tabindex="-1">加載模型 <a class="header-anchor" href="#加載模型" aria-label="Permalink to &quot;加載模型&quot;">​</a></h2><ol><li>在 KoboldCPP 中選擇模型文件並啟動。</li><li>確認能在其自帶聊天或 UI 里正常生成，再開對外 API。</li><li>記下你使用的上下文長度、GPU 層數等；先用默認能跑通即可。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./server">開啟 API / 局域網</a> → <a href="/ultra_guides/zh-TW/connect-app/minitavern">在 MiniTavern 中配置</a></p>',8)])])}const b=e(i,[["render",n]]);export{P as __pageData,b as default};
